def parse_kv(s: str) -> dict:
    """Parse a string of key=value pairs separated by semicolons into a dictionary.
    Backslash-escaped semicolons \; in values are treated as literal semicolons.
    Whitespace around keys and values is trimmed.
    Example: 'key1=value1; key2=value2' -> {'key1': 'value1', 'key2': 'value2'}
    """
    if not s:
        return {}
    # Replace escaped semicolons with a placeholder
    s = s.replace('\\;', '__TEMP_SEMICOLON__')
    pairs = s.split(';')
    result = {}
    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue
        if '=' not in pair:
            raise ValueError(f"Invalid pair (missing '='): {pair}")
        key, value = pair.split('=', 1)
        key = key.strip()
        value = value.strip()
        # Restore escaped semicolons
        value = value.replace('__TEMP_SEMICOLON__', '\;')
        result[key] = value
    return result

